package com.leotv.detail;
import android.app.Activity;import android.view.*;import android.widget.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=23,manifest=Config.NONE)
public class NativeHomeFocusTest {
 Activity activity;HomeFocusSubject subject;View hero;
 @Before public void open(){activity=Robolectric.buildActivity(Activity.class).setup().get();subject=new HomeFocusSubject(activity);activity.setContentView(subject.list);hero=new View(activity);hero.setFocusable(true);subject.list.addView(hero,new LinearLayout.LayoutParams(1280,720));layout();assertTrue(hero.requestFocus());}
 void layout(){View decor=activity.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(1280,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(720,View.MeasureSpec.EXACTLY));decor.layout(0,0,1280,720);}
 HomeFocusSubject.Row row(int count){HomeFocusSubject.Row r=new HomeFocusSubject.Row(activity,count);subject.entries.add(r.shelf);subject.attached.put(r.shelf,r);return r;}
 View card(HomeFocusSubject.Row row,int position){View card=new View(activity);card.setFocusable(true);card.setTag(position);row.grid.addView(card,new LinearLayout.LayoutParams(100,80));return card;}
 void mount(HomeFocusSubject.Row row){subject.list.addView(row.root,new LinearLayout.LayoutParams(400,160));layout();}
 @Test public void detachedRowDoesNotConsumePendingOrStealTheSourceFocus(){HomeFocusSubject.Row row=row(1);View target=card(row,0);assertTrue(subject.focus(row.shelf,0,0,false));assertSame(row.shelf,subject.pending);assertSame(hero,activity.getCurrentFocus());mount(row);subject.applyPending(row);assertNull(subject.pending);assertTrue(target.hasFocus());}
 @Test public void aRowWithoutAttachedCardsKeepsThePendingTargetUntilTheCardArrives(){HomeFocusSubject.Row row=row(1);mount(row);subject.focus(row.shelf,0,0,false);assertSame(row.shelf,subject.pending);assertSame(hero,activity.getCurrentFocus());View target=card(row,0);layout();subject.applyPending(row);assertNull(subject.pending);assertSame(target,activity.getCurrentFocus());}
 @Test public void selectedCardMustExistAndAcceptFocusBeforeTheHandoffCompletes(){HomeFocusSubject.Row row=row(3);card(row,0);mount(row);subject.focus(row.shelf,2,0,false);assertSame(row.shelf,subject.pending);assertSame(hero,activity.getCurrentFocus());View target=card(row,2);target.setEnabled(false);layout();subject.applyPending(row);assertSame(row.shelf,subject.pending);target.setEnabled(true);subject.applyPending(row);assertNull(subject.pending);assertEquals(2,row.shelf.selected);assertSame(target,activity.getCurrentFocus());}
 @Test public void failedMoreFocusCanBeRetriedWithoutLosingTheRow(){HomeFocusSubject.Row row=row(1);mount(row);row.open.setEnabled(false);subject.focus(row.shelf,0,0,true);assertSame(row.shelf,subject.pending);assertSame(hero,activity.getCurrentFocus());row.open.setEnabled(true);subject.applyPending(row);assertNull(subject.pending);assertTrue(row.open.hasFocus());}
 @Test public void offscreenUnboundDestinationRetainsTheExistingVisibleFocus(){HomeFocusSubject.CspHomePage.Shelf shelf=new HomeFocusSubject.CspHomePage.Shelf();subject.entries.add(shelf);subject.focus(shelf,0,0,false);assertSame(shelf,subject.pending);assertSame(hero,activity.getCurrentFocus());}
 @Test public void recentHistoryMustHandOffToAnActualCardAfterAttachment(){HomeFocusSubject.History history=new HomeFocusSubject.History(activity);subject.page.recent=history;subject.entries.add(history.root);subject.startHistory(0);assertTrue(subject.pendingHistory);assertSame(hero,activity.getCurrentFocus());subject.list.addView(history.root,new LinearLayout.LayoutParams(400,160));layout();subject.retryHistory();assertTrue("Focusing an empty history grid is not a completed card handoff",subject.pendingHistory);View card=new View(activity);card.setFocusable(true);card.setTag(0);history.cards.addView(card,new LinearLayout.LayoutParams(100,80));layout();subject.retryHistory();assertFalse(subject.pendingHistory);assertSame(card,activity.getCurrentFocus());}
}
